class Solution {
public:
    string longestPrefix(string s) {
        int n = s.size();
        for (int L = n - 1; L >= 1; --L)
            if (s.compare(0, L, s, n - L, L) == 0)
                return s.substr(0, L);
        return "";
    }
};

