class Solution:
    def longestPrefix(self, s: str) -> str:
        n = len(s)
        f = [0] * n
        j = 0
        for i in range(1, n):
            while j > 0 and s[i] != s[j]:
                j = f[j - 1]
            if s[i] == s[j]:
                j += 1
            f[i] = j
        return s[:f[-1]]

