        int n = s.size(), j = 0;
        vector<int> f(n, 0);
        for (int i = 1; i < n; ++i) {
            while (j > 0 && s[i] != s[j]) j = f[j - 1];
            if (s[i] == s[j]) ++j;
            f[i] = j;
        }
        return s.substr(0, f[n - 1]);
    }
};

