class Solution {
public:
    string longestPrefix(string s) {
        long long n = s.size();
        const long long MOD1 = 1000000007LL, MOD2 = 998244353LL, B1 = 131, B2 = 137;
        long long h1 = 0, h2 = 0, r1 = 0, r2 = 0, p1 = 1, p2 = 1, ans = 0;
        for (long long i = 0; i < n; ++i) {
            long long c = s[i];
            h1 = (h1 * B1 + c) % MOD1;
            h2 = (h2 * B2 + c) % MOD2;
            r1 = (r1 + c * p1) % MOD1;
            r2 = (r2 + c * p2) % MOD2;
            p1 = p1 * B1 % MOD1;
            p2 = p2 * B2 % MOD2;
            if (i + 1 < n && h1 == r1 && h2 == r2) ans = i + 1;
        }
        return s.substr(0, ans);
    }
};

